<?php
$primaryCandidate = (string) ($site['site_primary_color'] ?? '');
$primary = preg_match('/^#[0-9a-fA-F]{6}$/', $primaryCandidate) === 1 ? $primaryCandidate : (preg_match('/^#[0-9a-fA-F]{6}$/', (string) ($site['primary_color'] ?? '')) === 1 ? (string) $site['primary_color'] : '#ed1c24');
$secondaryCandidate = (string) ($site['site_secondary_color'] ?? '');
$secondary = preg_match('/^#[0-9a-fA-F]{6}$/', $secondaryCandidate) === 1 ? $secondaryCandidate : (preg_match('/^#[0-9a-fA-F]{6}$/', (string) ($site['secondary_color'] ?? '')) === 1 ? (string) $site['secondary_color'] : '#102a56');
$logo = (string) ($site['logo_path'] ?? '');
$favicon = (string) ($site['favicon_path'] ?? '');
$siteTitle = (string) ($site['site_title'] ?: $site['display_name']);
$seoTitle = (string) ($site['seo_title'] ?: $siteTitle);
$seoDescription = (string) ($site['seo_description'] ?: $site['hero_text']);
$templateKey = in_array((string) ($site['template_key'] ?? 'modern'), ['modern', 'classic', 'minimal'], true) ? (string) $site['template_key'] : 'modern';
$store = ($site['selected_mode'] ?? 'catalog') === 'store';
$publicBase = rtrim((string) $basePath, '/') . '/site';
$whatsappDigits = preg_replace('/\D+/', '', (string) ($site['whatsapp'] ?? '')) ?? '';
$whatsapp = $whatsappDigits !== '' ? (str_starts_with($whatsappDigits, '55') ? $whatsappDigits : '55' . $whatsappDigits) : '';
$whatsappMessage = rawurlencode((string) ($site['whatsapp_button_message'] ?? 'Olá! Gostaria de saber mais sobre os cursos.'));
$scholarshipEnabled = (int) ($site['scholarship_form_enabled'] ?? 0) === 1;
$scholarshipMode = (string) ($site['scholarship_display_mode'] ?? 'floating');
$scholarshipFloating = $scholarshipEnabled && in_array($scholarshipMode, ['floating', 'both'], true);
$scholarshipPopup = $scholarshipEnabled && in_array($scholarshipMode, ['popup', 'both'], true);
$footerText = trim((string) ($site['footer_text'] ?? ''));
$classroomUrl = trim((string) ($site['classroom_url'] ?? ''));
$classroomLabel = trim((string) ($site['classroom_label'] ?? 'Sala de Aula')) ?: 'Sala de Aula';
$webmailUrl = trim((string) ($site['webmail_url'] ?? ''));
$searchEnabled = (int) ($site['site_search_enabled'] ?? 1) === 1;
$socialBarEnabled = (int) ($site['social_bar_enabled'] ?? 1) === 1;
$privacyPolicy = trim((string) ($site['privacy_policy'] ?? ''));
$termsText = trim((string) ($site['terms_text'] ?? ''));
$cookieNotice = trim((string) ($site['cookie_notice'] ?? ''));
$cookieBannerEnabled = (int) ($site['cookie_banner_enabled'] ?? 1) === 1;
$previewDevice = !empty($preview) && (($previewDevice ?? 'desktop') === 'mobile') ? 'mobile' : 'desktop';
$socialLinks = [];
if (!empty($site['contact_email'])) $socialLinks[] = ['icon' => 'fa-solid fa-envelope', 'label' => 'E-mail', 'url' => 'mailto:' . $site['contact_email']];
if (!empty($site['facebook_url'])) $socialLinks[] = ['icon' => 'fa-brands fa-facebook-f', 'label' => 'Facebook', 'url' => $site['facebook_url']];
if (!empty($site['instagram_url'])) $socialLinks[] = ['icon' => 'fa-brands fa-instagram', 'label' => 'Instagram', 'url' => $site['instagram_url']];
if (!empty($site['youtube_url'])) $socialLinks[] = ['icon' => 'fa-brands fa-youtube', 'label' => 'YouTube', 'url' => $site['youtube_url']];
if (!empty($site['linkedin_url'])) $socialLinks[] = ['icon' => 'fa-brands fa-linkedin-in', 'label' => 'LinkedIn', 'url' => $site['linkedin_url']];
if (!empty($site['tiktok_url'])) $socialLinks[] = ['icon' => 'fa-brands fa-tiktok', 'label' => 'TikTok', 'url' => $site['tiktok_url']];
if ($whatsapp !== '') $socialLinks[] = ['icon' => 'fa-brands fa-whatsapp', 'label' => 'WhatsApp', 'url' => 'https://wa.me/' . $whatsapp];
$cnpjDigits = preg_replace('/\D+/', '', (string) ($site['cnpj'] ?? '')) ?? '';
$cnpj = strlen($cnpjDigits) === 14 ? substr($cnpjDigits, 0, 2) . '.' . substr($cnpjDigits, 2, 3) . '.' . substr($cnpjDigits, 5, 3) . '/' . substr($cnpjDigits, 8, 4) . '-' . substr($cnpjDigits, 12, 2) : $cnpjDigits;
$categories = [];
foreach (($site['offers'] ?? []) as $catalogProduct) {
    $category = trim((string) ($catalogProduct['category'] ?? '')) ?: 'Outros cursos';
    $categories[$category] = true;
}
$categories = array_keys($categories);
sort($categories, SORT_NATURAL | SORT_FLAG_CASE);
$formations = is_array($site['formations'] ?? null) ? $site['formations'] : [];
?>
